"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[6275],{6183(e){e.exports=JSON.parse('{"title":"Radix UI\ub294 \uc5b8\uc81c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294\uac00","date":"2026-02-25","coverUrl":"/kudzu-based-bench/assets/notion/908c53349e9eed9b.png","html":"<h1 data-notion-block-id=\\"30ce548d-8a8e-805b-8fd6-eb61f897fe32\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"30ce548d-8a8e-802b-a313-ecdcd653218e\\" id=\\"30ce548d-8a8e-802b-a313-ecdcd653218e\\">Radix UI\ub294 \uc5b8\uc81c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294\uac00</h2><a href=\\"https://shadcnspace.com/blog/radix-ui-vs-base-ui\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shadcnspace.com/blog/radix-ui-vs-base-ui</a><p data-notion-block-id=\\"311e548d-8a8e-8096-b702-ec698d9f93e2\\">Radix UI\uac00 \uac1c\ubc1c\uc774 \uba48\ucdc4\ub2e4\ub294 \uc18c\uc2dd\uc744 \ub4e3\uace0 \uadf8\ub97c \uc5b4\ub290\uc815\ub3c4 \uacc4\uc2b9\ud558\uace0 \uc788\ub2e4\ub294 Base UI\ub85c \uc62e\uaca8\uac14\ub2e4\ub294 \uc18c\uc2dd\uc744 \ub9ce\uc774 \ub4e3\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uadf8\ub7fc\uc5d0\ub3c4 Radix UI\uac00 \uc8fc\ub294 \uc7a5\uc810\uc774 \uc788\uc74c\uc744 Base UI\uc640 \ube44\uad50\ud574\uc11c \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc804\uccb4\uc801\uc73c\ub85c Base UI\uac00 \uac1c\ubc1c\uc790\uc5d0\uac8c \uc120\ud0dd\uc9c0\ub97c \ub9ce\uc774\uc8fc\uc9c0\ub9cc \ub108\ubb34 \ub9ce\uc740 \uc120\ud0dd\uc9c0\ub97c \uc8fc\uae30\uc5d0 \ube60\ub974\uac8c \uad6c\ucd95\ud558\uae30\uc5d0 \ubd80\uc871\ud568\uc744 \uc758\ubbf8\ud558\uace0, Radix UI\ub294 \uc8fc\uad00\uc801\uc778(\\"opnionated\\") \uc120\ud0dd\uc9c0\ub97c \uc81c\uacf5\ud558\uc9c0\ub9cc, \uadf8\ub9cc\ud07c \ube60\ub974\uac8c \uad6c\ucd95\ud560 \uc218\uc788\uc74c\uc744 <code>&#x3C;Dialog></code>\ucef4\ud3ec\ub10c\ud2b8\ub97c \uae30\uc900\uc73c\ub85c \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 React Aria\ub098 Ark UI\uac19\uc740 \uc120\ud0dd\uc9c0\ub3c4 \uc788\uc73c\ubbc0\ub85c, \uc120\ud0dd\uc744 \uc2e0\uc911\ud788 \ud574\uc57c \ud560 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"311e548d-8a8e-8040-b425-e613c8c6db2c\\" id=\\"311e548d-8a8e-8040-b425-e613c8c6db2c\\"><code>React.FC&#x3C;></code>\ub97c \ud3ec\uae30\ud574\ub77c</h2><a href=\\"https://engineering.gusto.com/the-journey-to-a-safer-frontend-why-we-removed-react-fc-095ff0b3e2e4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://engineering.gusto.com/the-journey-to-a-safer-frontend-why-we-removed-react-fc-095ff0b3e2e4</a><p data-notion-block-id=\\"30ce548d-8a8e-8010-aab8-d342b701aeef\\"><code>React.FC&#x3C;></code>\uc81c\ub108\ub9ad\uc744 \uc65c \ud3ec\uae30\ud588\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \ubc14\uafb8\ub294 \uac83\uc774 \uc5b4\ub5a4 \uc774\uc810\uc744 \uac00\uc838\uc624\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \ubc14\uafb8\ub294 \uc791\uc5c5\uc744 \uc790\ub3d9\ud654\ud558\uace0 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 props\ub098 \ud0c0\uc785 \ubd88\uc77c\uce58\ub97c \ud574\uacb0\ud588\ub294\uc9c0\uae4c\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uad00\ub828\ud574\uc11c <a href=\\"https://react-typescript-cheatsheet.netlify.app/docs/basic/getting-started/function_components\\">\uad8c\uc7a5\uc0ac\ud56d Cheatsheet</a>\uc774\ub098 <a href=\\"https://github.com/gndelia/codemod-replace-react-fc-typescript\\">codemod</a> \ub610\ud55c \ucc38\uace0\ud558\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"30ce548d-8a8e-80ab-a0ee-fcd199b6d304\\" id=\\"30ce548d-8a8e-80ab-a0ee-fcd199b6d304\\">JS \uc911\uc2ec \uc811\uadfc\ubc29\uc2dd\uc740 \uc9c0\uc18d\uac00\ub2a5\ud558\uc9c0 \uc54a\ub2e4</h2><a href=\\"https://sgom.es/posts/2026-02-13-js-heavy-approaches-are-not-compatible-with-long-term-performance-goals/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://sgom.es/posts/2026-02-13-js-heavy-approaches-are-not-compatible-with-long-term-performance-goals/</a><p data-notion-block-id=\\"311e548d-8a8e-8062-b94d-ca3ad02bd8ea\\">JS \uc911\uc2ec \uc811\uadfc\ubc29\uc2dd\uc758 \ud5c8\uc810\uc744 \uc0b4\ud3b4\ubcf4\uace0, \uadf8\uc758 \uc911\uc2ec\uc5d0 \uc788\ub294 React\uac00 \uc0ac\uc6a9\ud560 \uac00\uce58\uac00 \uc788\ub294\uc9c0 \uc8fc\uad00\uc801\uc778 \uc758\uacac\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubb3c\ub860 React\uac00 \uc8fc\ub294 \uc0dd\ud0dc\uacc4\uc758 \uc774\uc810\uacfc \ud504\ub860\ud2b8\uc5d4\ub4dc\ub97c \uc8fc\ub3c4\ud558\uace0 \uc788\uc74c\uc744 \ubb34\uc2dc\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc, <a href=\\"https://ones-to-watch.ethansup.net/news/post/262e548d-8a8e-80eb-9e8b-cd0868f2c950#279e548d-8a8e-80bc-bcfb-ea405e329206\\">\ub9ac\uc561\ud2b8\uc5d0 \uc228\uaca8\uc9c4 \ube44\uc6a9</a>\uc5d0\uc11c\ub3c4 \ub9d0\ud588\ub4ef\uc774 \uc548\uc815\uc131\uacfc \uc131\ub2a5\uc0c1 \ub2e8\uc810\uc774 \uc788\ub2e4\ub294 \uac83\uc740 \ubb34\uc2dc\ud560 \uc218 \uc5c6\ub294 \ubd80\ubd84\uc774\uae34 \ud569\ub2c8\ub2e4. \uc88b\uc740 \uc808\ucda9\uc810\uc744 \ucc3e\ub294 \uac83\uc774 \uc88b\uc544\ubcf4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"311e548d-8a8e-8029-a83a-cd93ec9fddbb\\" id=\\"311e548d-8a8e-8029-a83a-cd93ec9fddbb\\">\uc774\uc81c\ub294 CSS5\uc758 \uc2dc\ub300\uc785\ub2c8\ub2e4.</h2><a href=\\"https://modern-css.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://modern-css.com/</a><p data-notion-block-id=\\"30ce548d-8a8e-804d-a992-fcc7dd5616bd\\">CSS5\ub77c\uace0 \uce6d\ud560 \uc815\ub3c4\ub85c Baseline\uc5d0\uc11c \uc218\ub9ce\uc740 CSS\uac00 \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc5d0 \ub9ce\uc774 \uad6c\ud604\ub418\uc5c8\uc9c0\ub9cc, \uc6b0\ub9ac\ub294 \uadf8 CSS\ub97c \uc0ac\uc6a9\ud558\uace0 \uc788\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4(\uadf8\ub9ac\uace0 \uc544\uc9c1\ub3c4 CSS3\ub77c\uace0 \uce6d\ud558\uace0 \uc788\uc8e0 \ud83d\ude22). \uc774 \uc0ac\uc774\ud2b8\uc5d0\uc11c\ub294 CSS5\ub97c \uc911\uc2ec\uc73c\ub85c \ucd5c\uc2e0 CSS\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"30ce548d-8a8e-8089-81c8-ebfd0b03b562\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"311e548d-8a8e-80c7-aef1-c78e8faaed7d\\" id=\\"311e548d-8a8e-80c7-aef1-c78e8faaed7d\\">Streaming API \uac1c\uc120\uae30</h2><a href=\\"https://vercel.com/blog/we-ralph-wiggumed-webstreams-to-make-them-10x-faster\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/we-ralph-wiggumed-webstreams-to-make-them-10x-faster</a><p data-notion-block-id=\\"311e548d-8a8e-8086-a9d3-e942e5a327e1\\">\uc65c \ud45c\uc900\uc5d0 \ud574\ub2f9\ud558\ub294 Streaming API\uac00 \uae30\uc874\uc758 Streaming API\ubcf4\ub2e4 \ub290\ub9b0\uc9c0 \uc18c\uac1c\ud558\uace0, \uae30\uc874\uc758 Streaming API\ub97c \uae30\ubc18\uc73c\ub85c \ud45c\uc900 Streaming API\ub97c \uad6c\ud604\ud558\uc5ec \uc18d\ub3c4\ub97c \ube60\ub974\uac8c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"311e548d-8a8e-8029-b020-ea339dbeb14b\\" id=\\"311e548d-8a8e-8029-b020-ea339dbeb14b\\">Tanstack Query\uc5d0\uc11c \ucd94\uc0c1\ud654\ud558\uae30</h2><a href=\\"https://tkdodo.eu/blog/creating-query-abstractions\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/creating-query-abstractions</a><p data-notion-block-id=\\"311e548d-8a8e-80c7-9966-d21fb6aaf39e\\">\uc218\ub9ce\uc740 \uc0ac\ub78c\uc774 Tanstack Query\ub97c \uc0ac\uc6a9\ud560\ud150\ub370, \uc774 \ub54c \ud0c0\uc785 \ubd88\uc77c\uce58\ub098 Custom Hook\uc758 \ucd94\uc0c1\ud654 \uc5b4\ub824\uc6c0\uc744 queryOption API\ub97c \uc0ac\uc6a9\ud558\uba74 \ud574\uacb0\ud560 \uc218 \uc788\ub2e4\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"311e548d-8a8e-808c-8a47-cd998280abe0\\" id=\\"311e548d-8a8e-808c-8a47-cd998280abe0\\">Node.js\uc5d0\uc11c\uc758 \ud3ec\uc778\ud130 \uc555\ucd95</h2><a href=\\"https://blog.platformatic.dev/we-cut-nodejs-memory-in-half\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.platformatic.dev/we-cut-nodejs-memory-in-half</a><p data-notion-block-id=\\"30fe548d-8a8e-8074-a38d-ea4df5a854b8\\">Node.js\uc5d0\uc11c \ud3ec\uc778\ud130 \uc555\ucd95 \uae30\ub2a5\uc744 \ud65c\uc131\ud654\ud588\uc744 \uacbd\uc6b0\uc758 \uc774\uc810\uc744 \ubca4\uce58\ub9c8\ud06c \uae30\ubc18\uc73c\ub85c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uadf8\uc640 \ud568\uaed8 \uc5b4\ub5bb\uac8c \ud3ec\uc778\ud130 \uc555\ucd95 \uae30\ub2a5\uc744 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud558\ub294\uc9c0 \uc54c\ub824\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"30ce548d-8a8e-80de-b97c-e9dd69b11a3e\\" id=\\"30ce548d-8a8e-80de-b97c-e9dd69b11a3e\\">TypeScript \uc81c\ub124\ub9ad \uc2e4\uc0ac\uc6a9 \uc0ac\ub840</h2><a href=\\"https://frontendmasters.com/blog/fun-with-typescript-generics/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/fun-with-typescript-generics/</a><h2 data-notion-block-id=\\"30ce548d-8a8e-80f9-8c5f-d5c6b811dfff\\" id=\\"30ce548d-8a8e-80f9-8c5f-d5c6b811dfff\\">Node.js\uc5d0\uc11c <code>fetch()</code>\uc0ac\uc6a9\ubc95</h2><a href=\\"https://nodejsdesignpatterns.com/blog/nodejs-http-request/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodejsdesignpatterns.com/blog/nodejs-http-request/</a><h2 data-notion-block-id=\\"311e548d-8a8e-80b6-beb4-e2f344d992d2\\" id=\\"311e548d-8a8e-80b6-beb4-e2f344d992d2\\">AI \uae30\ubc18 \uc81c\ud488\uc5d0\ub294 \uc5b4\ub5a4 UX\uac00 \ud544\uc694\ud560\uae4c</h2><a href=\\"https://www.smashingmagazine.com/2026/02/designing-agentic-ai-practical-ux-patterns/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2026/02/designing-agentic-ai-practical-ux-patterns/</a><h1 data-notion-block-id=\\"30ce548d-8a8e-8047-a511-c2637b2a5b4d\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://blackboard.sh/blog/electrobun-v1/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blackboard.sh/blog/electrobun-v1/</a><p data-notion-block-id=\\"30fe548d-8a8e-8000-83de-ca6881cdb22e\\">Electron\uacfc Tauri\ub97c \uc65c \ud3ec\uae30\ud588\uace0, \uadf8\uc758 \ub300\uccb4\uc778 Electrobun\uc744 \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://styled-components.com/releases#styled-components@6.3.7\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://styled-components.com/releases#styled-components@6.3.7</a><p data-notion-block-id=\\"30ce548d-8a8e-807a-9d22-c9abe8866d43\\">\ucd5c\uadfc RSC\ub97c \uc9c0\uc6d0\ud558\uac8c \ub418\uba74\uc11c, styled-components\uac00 \uadf8\uc800 maintaining\ubaa8\ub4dc\uc5d0\uc11c \ub2e4\uc2dc \ud65c\ubc1c\ud558\uac8c \uac1c\ubc1c\ub418\uace0 \uc788\uc74c\uc73c\ub85c \ubc14\ub00c\uc5c8\uc74c\uc744 \ubcf4\uc5ec\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://tmikov.blogspot.com/2026/02/webassembly-comes-to-hermes_01829874520.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tmikov.blogspot.com/2026/02/webassembly-comes-to-hermes_01829874520.html</a><p data-notion-block-id=\\"30fe548d-8a8e-8048-b2d3-e2f50624eb92\\">WASM\ud30c\uc77c\uc744 Hermes\ucef4\ud30c\uc77c\ud560 \uc218 \uc788\uc74c\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://tiktok.github.io/sparkling/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tiktok.github.io/sparkling/</a><p data-notion-block-id=\\"30fe548d-8a8e-8090-ba68-e33bde3cd43e\\">Lynx \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uae30\ubc18\uc73c\ub85c \ube60\ub974\uac8c \uc571\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub294 \ud504\ub808\uc784\uc6cc\ud06c\uc778 Sparkling\uc785\ub2c8\ub2e4. React Native\uc758 \ub300\ud56d\ub9c8\ub85c\uc11c \uc88b\uc740 \uc0c1\ub300\uac00 \ub420\uc9c0 \uc8fc\ubaa9\ud574\ubcfc\ub9cc \ud560 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://www.repoflow.io/blog/node-js-vs-deno-vs-bun-performance-benchmarks\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.repoflow.io/blog/node-js-vs-deno-vs-bun-performance-benchmarks</a><p data-notion-block-id=\\"30fe548d-8a8e-809b-a5d5-e5d606c7ddd9\\">Node.js/Deno/Bun\uc758 \uc5ec\ub7ec \uc0c1\ud669\uc5d0\uc11c\uc758 \ub124\uc774\ud2f0\ube0c \uae30\ub2a5\uc744 \ud14c\uc2a4\ud2b8\ud55c \ubca4\uce58\ub9c8\ud06c\uc785\ub2c8\ub2e4.</p><a href=\\"https://tanstack.com/start/latest/docs/framework/react/guide/import-protection\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/start/latest/docs/framework/react/guide/import-protection</a><p data-notion-block-id=\\"30fe548d-8a8e-80a2-9307-eb0d8db017cf\\">Tanstack Start\uc5d0\uc11c <code>\\"import server-only\\"</code>\uc640 \uac19\uc740 import ~ \ud328\ud134\uc744 \uad6c\ud604\ud588\uc74c\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.react.doctor/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.react.doctor/</a><p data-notion-block-id=\\"311e548d-8a8e-8064-8df9-ecbaa9114165\\">React\uc5d0\uc11c \uc548\ud2f0\ud328\ud134\uc744 \ucc3e\uc544\uc8fc\ub294 \ub3c4\uad6c\uc778 React doctor\uc785\ub2c8\ub2e4.</p>"}')}}]);